package app.daemon.deck;
import android.app.*;import android.content.*;
public class AlarmReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if("dismiss".equals(i.getAction())){c.stopService(new Intent(c,AlarmService.class));return;}boolean alarm="alarm".equals(i.getStringExtra("type"));if(alarm){try{c.startForegroundService(new Intent(c,AlarmService.class).putExtras(i));return;}catch(Exception ignored){}}try{((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(i.getDataString()==null?1:i.getDataString().hashCode(),Alarms.notification(c,i,alarm));}catch(SecurityException ignored){}}}
